// Returns FALSE only if user cancels save action
if (
  gContentChanged ||
  gMsgCompose.bodyModified ||
  gAutoSaveKickedIn ||
  gReceiptOptionChanged ||
  gDSNOptionChanged
) {
  // call window.focus, since we need to pop up a dialog
  // and therefore need to be visible (to prevent user confusion)
  window.focus();
  const messengerBundle = Services.strings.createBundle(
    "chrome://messenger/locale/messenger.properties"
  );
  let draftsFolderName =
    messengerBundle.GetStringFromName("draftsFolderName");
  if (gCurrentIdentity.fccFolderURI) {
    const draftsFolder = MailUtils.getExistingFolder(
      gCurrentIdentity.fccFolderURI
    );
    if (draftsFolder) {
      draftsFolderName = draftsFolder.localizedName;
    }
  }
  const result = Services.prompt.confirmEx(
    window,
    lazy.l10n.formatValueSync("compose-save-message-title"),
    lazy.l10n.formatValueSync("compose-save-message-prompt", {
      folder: draftsFolderName,
    }),
